CREATE TABLE users (id text PRIMARY KEY, email text UNIQUE, password_hash text, name text NOT NULL, is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE INDEX sessions_expiry_idx ON sessions(expires_at);
CREATE TABLE oauth_states (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, session_id text NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE oauth_connections (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, provider text NOT NULL, provider_account_id text NOT NULL, username text NOT NULL, scopes text[] NOT NULL, encrypted_token text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,provider_account_id));
CREATE TABLE instagram_profiles (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, provider text NOT NULL, instagram_id text NOT NULL, username text NOT NULL, display_name text, biography text, profile_picture_url text, website text, followers_count bigint, following_count bigint, media_count integer, account_type text, verified boolean, source text NOT NULL, field_sources jsonb NOT NULL, retrieved_at timestamptz NOT NULL, color text NOT NULL DEFAULT '#a4f2ce', UNIQUE(user_id,provider,instagram_id));
CREATE INDEX profiles_username_idx ON instagram_profiles(user_id,username);
CREATE INDEX profiles_instagram_id_idx ON instagram_profiles(instagram_id);
CREATE TABLE tracked_profiles (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, profile_id text NOT NULL REFERENCES instagram_profiles(id) ON DELETE CASCADE, interval_minutes integer NOT NULL CHECK(interval_minutes>=60 AND interval_minutes<=10080), enabled boolean NOT NULL DEFAULT true, notify boolean NOT NULL DEFAULT true, next_run_at timestamptz NOT NULL DEFAULT now(), last_checked_at timestamptz, failures integer NOT NULL DEFAULT 0, last_error text, lease_until timestamptz, UNIQUE(user_id,profile_id));
CREATE INDEX tracked_due_idx ON tracked_profiles(enabled,next_run_at);
CREATE TABLE profile_snapshots (id text PRIMARY KEY, profile_id text NOT NULL REFERENCES instagram_profiles(id) ON DELETE CASCADE, tracked_profile_id text REFERENCES tracked_profiles(id) ON DELETE SET NULL, provider text NOT NULL, instagram_id text NOT NULL, username text NOT NULL, display_name text, biography text, profile_picture_url text, website text, followers_count bigint, following_count bigint, media_count integer, account_type text, verified boolean, source text NOT NULL, field_sources jsonb NOT NULL, retrieved_at timestamptz NOT NULL, fingerprint text NOT NULL, raw_provider_metadata jsonb NOT NULL DEFAULT '{}', UNIQUE(profile_id,retrieved_at));
CREATE INDEX snapshots_profile_time_idx ON profile_snapshots(profile_id,retrieved_at);
CREATE INDEX snapshots_tracked_idx ON profile_snapshots(tracked_profile_id);
CREATE TABLE tracking_events (id text PRIMARY KEY, profile_id text NOT NULL REFERENCES instagram_profiles(id) ON DELETE CASCADE, snapshot_id text REFERENCES profile_snapshots(id) ON DELETE CASCADE, event_type text NOT NULL, old_value jsonb, new_value jsonb, detected_at timestamptz NOT NULL, username text NOT NULL, source text NOT NULL);
CREATE INDEX events_profile_time_idx ON tracking_events(profile_id,detected_at);
CREATE INDEX events_type_idx ON tracking_events(event_type);
CREATE TABLE media (id text PRIMARY KEY, profile_id text NOT NULL REFERENCES instagram_profiles(id) ON DELETE CASCADE, provider_media_id text NOT NULL, username text NOT NULL, type text NOT NULL, caption text, permalink text, thumbnail_url text, media_url text, timestamp timestamptz NOT NULL, source text NOT NULL, field_sources jsonb NOT NULL, UNIQUE(profile_id,provider_media_id));
CREATE INDEX media_profile_time_idx ON media(profile_id,timestamp);
CREATE TABLE media_metrics (id text PRIMARY KEY, media_id text NOT NULL REFERENCES media(id) ON DELETE CASCADE, likes bigint, comments bigint, views bigint, reach bigint, saved bigint, shares bigint, impressions bigint, duration numeric, retrieved_at timestamptz NOT NULL);
CREATE INDEX media_metrics_id_time_idx ON media_metrics(media_id,retrieved_at);
CREATE TABLE notification_rules (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, profile_id text REFERENCES instagram_profiles(id) ON DELETE CASCADE, event_type text NOT NULL, threshold bigint, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE notifications (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, event_id text REFERENCES tracking_events(id) ON DELETE CASCADE, title text NOT NULL, body text NOT NULL, username text, event_type text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,event_id));
CREATE INDEX notification_user_idx ON notifications(user_id,created_at);
CREATE TABLE saved_profiles (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, profile_id text NOT NULL REFERENCES instagram_profiles(id) ON DELETE CASCADE, notes text NOT NULL DEFAULT '', label text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,profile_id));
CREATE TABLE tags (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, UNIQUE(user_id,name));
CREATE TABLE profile_tags (saved_profile_id text NOT NULL REFERENCES saved_profiles(id) ON DELETE CASCADE, tag_id text NOT NULL REFERENCES tags(id) ON DELETE CASCADE, PRIMARY KEY(saved_profile_id,tag_id));
CREATE TABLE provider_requests (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, request_id text NOT NULL, provider text NOT NULL, operation text NOT NULL, status integer NOT NULL, duration_ms integer NOT NULL, cache_hit boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX provider_requests_time_idx ON provider_requests(user_id,created_at);
CREATE TABLE system_status (key text PRIMARY KEY, value text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
